def risk_name(flag: str, lang: str) -> str:
    return RISK_NAMES.get(flag, {}).get(lang) or flag.replace("_", " ")


def t(key: str, lang: str, **kw) -> str:
    entry = S[key]
    s = entry.get(lang) or entry["en"]
    return s.format(**kw) if kw else s
